/* ---------- T46 阶段2（2026-09-19）：题库语音 clip 键（题面/选项串/类别/纠错全在册）
   键 1 基：qz_q_1=QZ_BANK[0] 题面 / qz_opts_1='选项有：'+opts.join('，') / qz_cat_N=CATS[N]（N 1-4）
   / qz_no=教学排除纠错句——manifest 330 条与 QZ_BANK 程序化对账（build 侧全量复核）。
   qid 0 基（game-core qid: bi）→ 键 +1 换算在此收敛。 */
const qKeyOf = q => 'qz_q_' + (q.qid + 1);
const optsKeyOf = q => 'qz_opts_' + (q.qid + 1);
const catKeyOf = q => 'qz_cat_' + q.cat;
